13	async function upsertDocFTS(env: Env, docId: string, title: string, body: string): Promise<void> {
14	  await env.DB.prepare('DELETE FROM docs_fts WHERE doc_id = ?').bind(docId).run();
15	  const plainBody = stripMarkdownForFTS(body);
16	  await env.DB.prepare('INSERT INTO docs_fts (doc_id, title, body) VALUES (?, ?, ?)').bind(docId, title, plainBody).run();
17	}
18	
19	export const importRoute = new Hono<AppEnv>()
20	  .post('/markdown', async (c) => {
21	    const data = await validateBody(c, importMarkdownSchema);
22	    if (isResponse(data)) return data;
23	
24	    const title = data.title.trim();
25	    const rawPath = data.path.trim();
26	    const markdown = data.markdown;
27	    const folderId = data.folderId;
28	    const overwrite = data.overwrite;
29	
30	    const path = rawPath.startsWith('/') ? rawPath : `/${rawPath}`;
31	    const workspaceId = c.get('workspaceId');
32	
33	    // A client-supplied folderId must belong to the caller's workspace,
34	    // or the imported doc would carry a cross-workspace folder reference.
35	    if (folderId) {
36	      const folder = await getFolder(c.env, folderId, workspaceId);
37	      if (!folder) return jsonError(c, 400, 'VALIDATION_ERROR', 'folderId does not exist in this workspace', { folderId });
38	    }
39	
40	    try {
41	      // Scope by workspace: docs has UNIQUE(workspace_id, path), so the
42	      // same path legitimately exists in other workspaces. An unscoped
43	      // lookup matched a foreign doc — overwrite=true then R2.put() over
44	      // its body, and overwrite=false 409-leaked its id.
45	      const existing = await getDocByPath(c.env, path, { workspaceId });
46	      if (existing && !overwrite) {
47	        return jsonError(c, 409, 'CONFLICT', 'path already exists', { path, existingId: existing.id });
48	      }
49	
50	      if (existing && overwrite) {
51	        await c.env.R2.put(existing.r2Key, markdown, {
52	          httpMetadata: { contentType: 'text/markdown; charset=utf-8' }
53	        });
54	        await updateDocMeta(c.env, existing.id, workspaceId, { title, path, folderId });
55	        await replaceWikilinksForDoc(c.env, { workspaceId, fromDocId: existing.id, refs: extractWikilinks(markdown) });
56	        await upsertDocFTS(c.env, existing.id, title, markdown);
57	        return c.json({ ok: true, mode: 'updated', id: existing.id, path });
58	      }
59	
60	      const id = `doc_${crypto.randomUUID()}`;
61	      const r2Key = `workspace/${workspaceId}/docs/${id}.md`;
62	      await c.env.R2.put(r2Key, markdown, {
63	        httpMetadata: { contentType: 'text/markdown; charset=utf-8' }
64	      });
65	
66	      await createDocMeta(c.env, {
67	        id,
68	        title,
69	        path,
70	        r2Key,
71	        createdBy: c.get('userId'),
72	        // Omitted folderId → the caller workspace's own /imported folder,
73	        // not the ws_demo-only 'folder_concepts' the schema used to default.
74	        folderId: folderId ?? await ensureImportFolder(c.env, workspaceId),
75	        workspaceId
76	      });
77	
78	      await replaceWikilinksForDoc(c.env, { workspaceId, fromDocId: id, refs: extractWikilinks(markdown) });
79	      await upsertDocFTS(c.env, id, title, markdown);
80	
81	      return c.json({ ok: true, mode: 'created', id, path }, 201);
