15	  await env.DB.prepare('DELETE FROM docs_fts WHERE doc_id = ?').bind(docId).run();
16	  const plainBody = stripMarkdownForFTS(body);
17	  await env.DB.prepare('INSERT INTO docs_fts (doc_id, title, body) VALUES (?, ?, ?)')
18	    .bind(docId, title, plainBody).run();
19	}
