21	/** Parse YAML frontmatter from markdown, return { tags, title, body } */
22	function parseFrontmatter(markdown: string): {
23	  title: string | null;
24	  tags: string[];
25	  body: string;
26	} {
27	  const fmRegex = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/;
28	  const match = markdown.match(fmRegex);
29	  if (!match) return { title: null, tags: [], body: markdown };
30	
31	  const fmBlock = match[1];
32	  const body = markdown.slice(match[0].length);
33	
34	  let title: string | null = null;
35	  const tags: string[] = [];
36	
37	  for (const line of fmBlock.split('\n')) {
38	    const trimmed = line.trim();
39	    if (trimmed.startsWith('title:')) {
40	      title = trimmed.slice(6).trim().replace(/^["']|["']$/g, '');
41	    }
42	    if (trimmed.startsWith('tags:')) {
43	      // Inline: tags: [a, b, c] or tags: a, b, c
44	      const inline = trimmed.slice(5).trim();
45	      if (inline.startsWith('[')) {
46	        const inner = inline.replace(/^\[|\]$/g, '');
47	        tags.push(...inner.split(',').map((t) => t.trim().replace(/^["']|["']$/g, '')).filter(Boolean));
48	      } else if (inline) {
49	        tags.push(...inline.split(',').map((t) => t.trim().replace(/^["']|["']$/g, '')).filter(Boolean));
50	      }
51	    }
52	    // YAML list items under tags:
53	    if (trimmed.startsWith('- ') && tags.length === 0) {
54	      // Only if we're in a tags context - skip for safety
55	    }
56	  }
57	
58	  // Also check for list-style tags
59	  const tagListRegex = /^tags:\s*\n((?:\s*-\s*.+\n?)+)/m;
60	  const tagListMatch = fmBlock.match(tagListRegex);
61	  if (tagListMatch) {
62	    const listItems = tagListMatch[1].match(/^\s*-\s*(.+)/gm);
63	    if (listItems) {
64	      for (const item of listItems) {
65	        const val = item.replace(/^\s*-\s*/, '').trim().replace(/^["']|["']$/g, '');
66	        if (val && !tags.includes(val)) tags.push(val);
67	      }
68	    }
69	  }
70	
71	  return { title, tags, body };
72	}
