1	import { describe, it, expect, beforeAll, beforeEach } from 'vitest';
2	import { SELF, env } from 'cloudflare:test';
3	import { applyMigrations } from './setup';
4	
5	/**
6	 * Bulk import must place docs in a folder that belongs to the caller's
7	 * workspace.
8	 *
9	 * import-bulk.ts hardcoded folderId 'folder_concepts' — a folder
10	 * seeded only in ws_demo (0003_demo_folders.sql). For any other
11	 * workspace that planted the imported doc under a ws_demo-owned
12	 * folder (a cross-workspace folder reference) or failed the
13	 * docs.folder_id FK outright. The fix find-or-creates a per-workspace
14	 * /imported folder.
15	 */
16	
17	function token(): string {
18	  return (env as { INTERNAL_TOKEN: string }).INTERNAL_TOKEN;
19	}
20	
21	beforeAll(async () => {
22	  await applyMigrations();
23	});
24	
25	beforeEach(async () => {
26	  // Clear anything a prior run left in the default workspace's import area.
27	  await env.DB.prepare(`DELETE FROM docs WHERE workspace_id = 'ws_default' AND path LIKE '/import-bulk-test/%'`).run();
28	  await env.DB.prepare(`DELETE FROM folders WHERE workspace_id = 'ws_default' AND path = '/imported'`).run();
29	});
30	
31	async function importObsidian(filename: string, content: string): Promise<Response> {
32	  return SELF.fetch('http://localhost/import-bulk/obsidian', {
33	    method: 'POST',
34	    headers: { 'X-API-Key': token(), 'Content-Type': 'application/json' },
35	    body: JSON.stringify({ basePath: '/import-bulk-test', files: [{ filename, content }] }),
36	  });
37	}
38	
39	describe('POST /import-bulk/obsidian — import folder', () => {
40	  it('places the imported doc in an /imported folder owned by the caller workspace', async () => {
41	    const res = await importObsidian('note-a.md', '# Note A\n\nbody');
42	    expect(res.status).toBe(200);
43	    const json = await res.json() as { results: Array<{ status: string; id?: string }> };
44	    expect(json.results[0].status).toBe('created');
45	    const docId = json.results[0].id!;
46	
47	    const doc = await env.DB
48	      .prepare(`SELECT folder_id as folderId FROM docs WHERE id = ?`)
49	      .bind(docId)
50	      .first<{ folderId: string }>();
51	    expect(doc?.folderId).toBeTruthy();
52	    // The doc's folder must NOT be the ws_demo-only demo folder...
53	    expect(doc?.folderId).not.toBe('folder_concepts');
54	    // ...it must be a folder in the caller's own workspace.
55	    const folder = await env.DB
56	      .prepare(`SELECT workspace_id as ws, path FROM folders WHERE id = ?`)
57	      .bind(doc!.folderId)
58	      .first<{ ws: string; path: string }>();
59	    expect(folder?.ws).toBe('ws_default');
60	    expect(folder?.path).toBe('/imported');
61	  });
62	
63	  it('reuses the same /imported folder across imports (find-or-create)', async () => {
64	    const r1 = await importObsidian('first.md', '# First');
65	    const r2 = await importObsidian('second.md', '# Second');
66	    const id1 = (await r1.json() as { results: Array<{ id: string }> }).results[0].id;
67	    const id2 = (await r2.json() as { results: Array<{ id: string }> }).results[0].id;
68	
69	    const f1 = await env.DB.prepare(`SELECT folder_id as f FROM docs WHERE id = ?`).bind(id1).first<{ f: string }>();
70	    const f2 = await env.DB.prepare(`SELECT folder_id as f FROM docs WHERE id = ?`).bind(id2).first<{ f: string }>();
71	    expect(f1?.f).toBe(f2?.f);
72	    // Exactly one /imported folder exists — not one per import.
73	    const count = await env.DB
74	      .prepare(`SELECT COUNT(*) as n FROM folders WHERE workspace_id = 'ws_default' AND path = '/imported'`)
75	      .first<{ n: number }>();
76	    expect(count?.n).toBe(1);
77	  });
78	});
79

