1	import { describe, it, expect, beforeAll, beforeEach } from 'vitest';
2	import { SELF, env } from 'cloudflare:test';
3	import { applyMigrations } from './setup';
4	
5	/**
6	 * Cross-workspace destructive write in POST /import/markdown.
7	 *
8	 * docs has UNIQUE(workspace_id, path) — the same path legitimately
9	 * exists in multiple workspaces. The handler looked up the existing
10	 * doc with getDocByPath(c.env, path) — NO workspaceId — so a path that
11	 * collides with another workspace's doc matched that foreign doc. With
12	 * overwrite=true the handler then R2.put(existing.r2Key, ...) — i.e.
13	 * overwrote the foreign workspace's doc body. With overwrite=false it
