295	  const t0 = Date.now();
296	  const sql = `INSERT INTO tasks (
297	      id, workspace_id, title, description, description_r2_key, status, priority, assignee_id, due_at,
298	      recurrence_rule, created_by, created_at, updated_at, archived_at
299	    ) VALUES (
